def _json_bytes(value: Any) -> bytes:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")


def _parse_replication_pairs(query: Mapping[str, list[str]]) -> list[tuple[str, str, str]]:
    """Parse repeatable persisted packet pair references shared by release routes."""

    raw_pairs = query.get("pair", [])
    if not raw_pairs:
        raise ValueError("at least one pair=PAIR_ID=LEFT=RIGHT query value is required")
    pairs = []
    for raw_pair in raw_pairs:
        parts = raw_pair.split("=", 2)
        if len(parts) != 3 or not all(parts):
            raise ValueError("pair values must use PAIR_ID=LEFT=RIGHT")
        pairs.append((parts[0], parts[1], parts[2]))
    return pairs


def _parse_review_decisions(
    query: Mapping[str, list[str]], prefix: str = ""
) -> tuple[dict[str, Any], ...]:
    """Parse compact review decision query values without introducing identity fields."""

    raw_decisions = query.get(f"{prefix}decision", [])
    entry_ids = query.get(f"{prefix}entry_id", [])
    rationales = query.get(f"{prefix}rationale", [])
    action_values = query.get(f"{prefix}required_action", [])
    actions: dict[str, list[str]] = {}
    for raw_action in action_values:
        parts = raw_action.split("=", 1)
        if len(parts) == 2 and all(parts):
            actions.setdefault(parts[0], []).append(parts[1])
        elif raw_action:
            action_key = entry_ids[-1] if entry_ids else "review-0"
            actions.setdefault(action_key, []).append(raw_action)
    decisions: list[dict[str, Any]] = []
    for index, raw_decision in enumerate(raw_decisions):
        parts = raw_decision.split("=", 2)
        if len(parts) == 3 and all(parts):
            entry_id, decision, rationale = parts
        elif len(parts) == 2 and all(parts):
            entry_id, decision = parts
            rationale = rationales[index] if index < len(rationales) else "explicit release-window review decision"
        elif len(parts) == 1 and parts[0]:
            entry_id = entry_ids[index] if index < len(entry_ids) else f"{prefix or 'review-'}{index}"
            decision = parts[0]
            rationale = rationales[index] if index < len(rationales) else "explicit release-window review decision"
        else:
            raise ValueError("decision values must use ENTRY_ID=DECISION=RATIONALE or DECISION")
        decisions.append(
            {
                "entry_id": entry_id,
                "decision": decision,
                "rationale": rationale,
                "required_actions": tuple(actions.get(entry_id, ())),
            }
        )
    return tuple(decisions)


class ApiHandler(BaseHTTPRequestHandler):
    """Small API handler with explicit endpoints and bounded error bodies."""

    server_version = "glio-noncode/0.1"
    runtime_factory: Callable[[], CaseRuntime] | None = None

    def _runtime(self) -> CaseRuntime:
        factory = self.runtime_factory or (lambda: CaseRuntime())
        runtime = getattr(self.server, "glio_runtime", None)
        if runtime is None:
            runtime = factory()
            setattr(self.server, "glio_runtime", runtime)  # noqa: B010 - the HTTP server is intentionally extended
        return runtime

    def _module_certification_context(
        self, *, include_certification: bool = True
    ) -> tuple[Any, Any, Any, Any, Any]:
        """Cache the immutable repository aggregate for related read routes."""

        context = getattr(self.server, "glio_module_certification_context", None)
        if context is None:
            inventory = build_module_inventory()
            matrix = build_module_certification(inventory)
            plan = build_module_certification_task_plan(matrix) if include_certification else None
            gate = evaluate_module_certification_gate(matrix, plan) if plan is not None else None
            runtime = run_module_certification(inventory=inventory) if include_certification else None
            context = (inventory, matrix, plan, gate, runtime)
            setattr(self.server, "glio_module_certification_context", context)  # noqa: B010 - server-local cache
        elif include_certification and context[2] is None:
            inventory, matrix, _, _, _ = context
            plan = build_module_certification_task_plan(matrix)
            gate = evaluate_module_certification_gate(matrix, plan)
            runtime = run_module_certification(inventory=inventory)
            context = (inventory, matrix, plan, gate, runtime)
            setattr(self.server, "glio_module_certification_context", context)  # noqa: B010 - server-local cache
        return context

    def _deployment_guard(self) -> DeploymentGuard:
        guard = getattr(self.server, "glio_deployment_guard", None)
        if guard is None:
            guard = DeploymentGuard(default_deployment_profile("127.0.0.1"))
            setattr(self.server, "glio_deployment_guard", guard)  # noqa: B010 - server-local policy attachment
        return guard

    def _authorize_request(self) -> bool:
        """Apply the deployment profile before dispatching any API route."""

        authorization = self.headers.get("Authorization", "")
        token = authorization[7:].strip() if authorization.lower().startswith("bearer ") else None
        decision = self._deployment_guard().authorize(
            self.command,
            urlsplit(self.path).path,
            token=token,
        )
        if decision.allowed:
            return True
        status = HTTPStatus.UNAUTHORIZED if decision.reason == "missing_or_invalid_credential" else HTTPStatus.FORBIDDEN
        self._write(
            status,
            {
                "error": "authentication_required" if status is HTTPStatus.UNAUTHORIZED else "forbidden",
                "message": decision.reason,
                "operation": decision.operation.value,
                "audit_sequence": decision.audit_sequence,
            },
            headers={"WWW-Authenticate": "Bearer"} if status is HTTPStatus.UNAUTHORIZED else None,
        )
        return False

    def _program_offline_bundle(self, bundle_id: str, run_id: str):
        """Reuse one immutable offline build across related GET projections."""

        cache = getattr(self.server, "glio_program_offline_bundles", None)
        if cache is None:
            cache = {}
            self.server.glio_program_offline_bundles = cache
        key = (bundle_id, run_id)
        bundle = cache.get(key)
        if bundle is None:
            bundle = build_program_runtime_offline_bundle(bundle_id=bundle_id, run_id=run_id)
            cache[key] = bundle
        return bundle

    def _program_release_closure_source(self, bundle_id: str, run_id: str):
        """Cache the expensive sixteen-domain source handoff for closure routes."""

        cache = getattr(self.server, "glio_program_release_closure_sources", None)
        if cache is None:
            cache = {}
            self.server.glio_program_release_closure_sources = cache
        key = (bundle_id, run_id)
        bundle = cache.get(key)
        if bundle is None:
            bundle = self._program_offline_bundle(bundle_id, run_id)
            cache[key] = bundle
        return bundle

    def _service_surface(self):
        snapshot = getattr(self.server, "glio_service_surface", None)
        if snapshot is None:
            snapshot = build_service_surface_snapshot()
            setattr(self.server, "glio_service_surface", snapshot)  # noqa: B010 - lazy server-local cache
        return snapshot

    def _reference_manifest(self):
        """Cache one immutable source receipt manifest per server instance."""

        manifest = getattr(self.server, "glio_reference_manifest", None)
        if manifest is None:
            manifest = build_default_reference_manifest()
            setattr(self.server, "glio_reference_manifest", manifest)  # noqa: B010 - server-local manifest cache
        return manifest

    def _service_release(self, bundle_id: str):
        """Cache one service-release registry per requested bundle identifier."""

        cache = getattr(self.server, "glio_service_release_snapshots", None)
        if cache is None:
            cache = {}
            self.server.glio_service_release_snapshots = cache
        snapshot = cache.get(bundle_id)
        if snapshot is None:
            snapshot = build_service_release_snapshot(self._service_surface(), bundle_id=bundle_id)
            cache[bundle_id] = snapshot
        return snapshot

    def _release_assurance(self, bundle_id: str, run_id: str):
        """Cache one aggregate release-assurance snapshot per request identity."""

        cache = getattr(self.server, "glio_release_assurance_snapshots", None)
        if cache is None:
            cache = {}
            self.server.glio_release_assurance_snapshots = cache
        key = (bundle_id, run_id)
        snapshot = cache.get(key)
        if snapshot is None:
            snapshot = build_release_assurance_snapshot(
                self._service_surface(), bundle_id=bundle_id, run_id=run_id
            )
            cache[key] = snapshot
        return snapshot

    def _release_assurance_attestation(self, bundle_id: str, run_id: str):
        """Cache one final cross-plane attestation per request identity."""

        cache = getattr(self.server, "glio_release_assurance_attestations", None)
        if cache is None:
            cache = {}
            setattr(self.server, "glio_release_assurance_attestations", cache)  # noqa: B010 - server-local immutable cache
        key = (bundle_id, run_id)
        attestation = cache.get(key)
        if attestation is None:
            runtime = run_release_assurance(self._service_surface(), bundle_id=bundle_id, run_id=run_id)
            attestation = build_release_assurance_attestation(runtime, bundle_id=bundle_id, run_id=run_id)
            cache[key] = attestation
        return attestation

    @staticmethod
    def _query_value(query: dict[str, list[str]], name: str) -> str | None:
        values = query.get(name, [])
        if len(values) > 1:
            raise ValueError(f"query parameter {name} may only be supplied once")
        return values[0] if values else None

    @staticmethod
    def _query_values(query: dict[str, list[str]], name: str) -> tuple[str, ...]:
        values = query.get(name, [])
        selected: list[str] = []
        for value in values:
            for item in value.split(","):
                normalized = item.strip()
                if normalized and normalized not in selected:
                    selected.append(normalized)
        return tuple(selected)

    @classmethod
    def _query_bool(cls, query: dict[str, list[str]], name: str) -> bool:
        value = cls._query_value(query, name)
        if value is None:
            return False
        normalized = value.lower()
        if normalized in {"1", "true", "yes"}:
            return True
        if normalized in {"0", "false", "no"}:
            return False
        raise ValueError(f"query parameter {name} must be true or false")

    @classmethod
    def _query_int(cls, query: dict[str, list[str]], name: str, default: int) -> int:
        value = cls._query_value(query, name)
        if value is None:
            return default
        try:
            return int(value)
        except ValueError as exc:
            raise ValueError(f"query parameter {name} must be an integer") from exc

    @classmethod
    def _query_optional_int(cls, query: dict[str, list[str]], name: str) -> int | None:
        value = cls._query_value(query, name)
        if value is None:
            return None
        try:
            return int(value)
        except ValueError as exc:
            raise ValueError(f"query parameter {name} must be an integer") from exc

    @classmethod
    def _query_float(cls, query: dict[str, list[str]], name: str) -> float | None:
        value = cls._query_value(query, name)
        if value is None:
            return None
        try:
            return float(value)
        except ValueError as exc:
            raise ValueError(f"query parameter {name} must be a number") from exc

    @staticmethod
    def _certificate_from_document(raw: Mapping[str, Any]):
        """Resolve a certificate from a runtime, package, or certificate document."""

        if "gate_runtime" in raw and "certificate" in raw:
            return registry_federation_consensus_gate_certificate_runtime_model.runtime_from_mapping(raw).certificate
        if "consensus_runtime" in raw and "gate" in raw and "audit" in raw and "query" in raw:
            return registry_federation_consensus_gate_certificate_model.evaluate_certificate(
                registry_federation_consensus_gate_runtime_model.runtime_from_mapping(raw)
            )
        if "runtime" in raw and "gate" in raw and "gate_audit" in raw and "certificate" in raw:
            return registry_federation_consensus_gate_certificate_package_model.package_from_mapping(raw).certificate
        return registry_federation_consensus_gate_certificate_model.certificate_from_mapping(raw)

    @staticmethod
    def _certificate_and_audit_from_document(raw: Mapping[str, Any]):
        """Resolve a certificate and its audit from any public handoff document."""

        if "gate_runtime" in raw and "certificate" in raw:
            runtime = registry_federation_consensus_gate_certificate_runtime_model.runtime_from_mapping(raw)
            return runtime.certificate, runtime.certificate_audit
        if "runtime" in raw and "gate" in raw and "gate_audit" in raw and "certificate" in raw:
            package = registry_federation_consensus_gate_certificate_package_model.package_from_mapping(raw)
            return package.certificate, package.certificate_audit
        certificate = ApiHandler._certificate_from_document(raw)
        return certificate, registry_federation_consensus_gate_certificate_audit_model.audit_certificate(certificate)

